for (const item of items) {
    item.json.revenue =
        Number(item.json.transaction_qty) *
        Number(item.json.unit_price);
}

return items;

const items = $input.all();

// --------------------
// BASIC VARIABLES
// --------------------

let totalRevenue = 0;
let totalQuantity = 0;

const transactionIds = new Set();

const storeRevenue = {};
const categoryRevenue = {};
const productRevenue = {};
const productQuantity = {};
const hourlyRevenue = {};
const dailyRevenue = {};

let validRows = 0;
let invalidRows = 0;


// --------------------
// PROCESS ALL ROWS
// --------------------

for (const item of items) {

    const d = item.json;

    // Skip invalid rows if Data Quality node exists
    if (d.is_valid === false) {
        invalidRows++;
        continue;
    }

    validRows++;

    const revenue = Number(d.revenue || 0);
    const qty = Number(d.transaction_qty || 0);

    totalRevenue += revenue;
    totalQuantity += qty;

    if (d.transaction_id !== undefined) {
        transactionIds.add(String(d.transaction_id));
    }


    // STORE REVENUE
    const store = d.store_location || "Unknown";

    if (!storeRevenue[store]) {
        storeRevenue[store] = 0;
    }

    storeRevenue[store] += revenue;


    // CATEGORY REVENUE
    const category = d.product_category || "Unknown";

    if (!categoryRevenue[category]) {
        categoryRevenue[category] = 0;
    }

    categoryRevenue[category] += revenue;


    // PRODUCT REVENUE + QUANTITY
    const product = d.product_detail || "Unknown";

    if (!productRevenue[product]) {
        productRevenue[product] = 0;
        productQuantity[product] = 0;
    }

    productRevenue[product] += revenue;
    productQuantity[product] += qty;


    // HOURLY REVENUE
    if (d.transaction_time) {

        const hour = String(d.transaction_time).split(":")[0];

        if (!hourlyRevenue[hour]) {
            hourlyRevenue[hour] = 0;
        }

        hourlyRevenue[hour] += revenue;
    }


    // DAILY REVENUE
    if (d.transaction_date) {

        const date = String(d.transaction_date);

        if (!dailyRevenue[date]) {
            dailyRevenue[date] = 0;
        }

        dailyRevenue[date] += revenue;
    }
}


// --------------------
// HELPER FUNCTIONS
// --------------------

function sortDescending(obj) {
    return Object.entries(obj)
        .sort((a, b) => b[1] - a[1]);
}

function sortAscending(obj) {
    return Object.entries(obj)
        .sort((a, b) => a[1] - b[1]);
}


// --------------------
// BASIC KPIs
// --------------------

const totalTransactions = transactionIds.size;

const averageTransactionValue =
    totalTransactions > 0
        ? totalRevenue / totalTransactions
        : 0;


const storesSorted = sortDescending(storeRevenue);
const categoriesSorted = sortDescending(categoryRevenue);
const productsSorted = sortDescending(productRevenue);
const hoursSorted = sortDescending(hourlyRevenue);
const datesSorted = sortDescending(dailyRevenue);


// --------------------
// TOP / LOW PERFORMERS
// --------------------

const topStore = storesSorted[0] || ["N/A", 0];
const topCategory = categoriesSorted[0] || ["N/A", 0];
const topProduct = productsSorted[0] || ["N/A", 0];

const lowestProduct =
    sortAscending(productRevenue)[0] || ["N/A", 0];

const busiestHour =
    hoursSorted[0] || ["N/A", 0];

const slowestHour =
    sortAscending(hourlyRevenue)[0] || ["N/A", 0];

const bestDay =
    datesSorted[0] || ["N/A", 0];

const worstDay =
    sortAscending(dailyRevenue)[0] || ["N/A", 0];


// --------------------
// TOP 5 PRODUCTS
// --------------------

const top5Products = productsSorted
    .slice(0, 5)
    .map(([name, revenue]) => ({
        name,
        revenue: Number(revenue.toFixed(2)),
        quantity: productQuantity[name] || 0
    }));


// --------------------
// BOTTOM 5 PRODUCTS
// --------------------

const bottom5Products = sortAscending(productRevenue)
    .slice(0, 5)
    .map(([name, revenue]) => ({
        name,
        revenue: Number(revenue.toFixed(2)),
        quantity: productQuantity[name] || 0
    }));


// --------------------
// STORE RANKING
// --------------------

const storeRanking = storesSorted.map(
    ([name, revenue], index) => ({
        rank: index + 1,
        name,
        revenue: Number(revenue.toFixed(2)),
        contributionPercent:
            totalRevenue > 0
                ? Number(((revenue / totalRevenue) * 100).toFixed(2))
                : 0
    })
);


// --------------------
// CATEGORY CONTRIBUTION
// --------------------

const categoryContribution = categoriesSorted.map(
    ([name, revenue]) => ({
        name,
        revenue: Number(revenue.toFixed(2)),
        contributionPercent:
            totalRevenue > 0
                ? Number(((revenue / totalRevenue) * 100).toFixed(2))
                : 0
    })
);


// --------------------
// DAILY GROWTH
// --------------------

const chronologicalDates =
    Object.keys(dailyRevenue).sort();

let dailyGrowthPercent = null;

if (chronologicalDates.length >= 2) {

    const latestDate =
        chronologicalDates[chronologicalDates.length - 1];

    const previousDate =
        chronologicalDates[chronologicalDates.length - 2];

    const latestRevenue =
        dailyRevenue[latestDate];

    const previousRevenue =
        dailyRevenue[previousDate];

    if (previousRevenue > 0) {

        dailyGrowthPercent =
            Number(
                (
                    ((latestRevenue - previousRevenue)
                    / previousRevenue) * 100
                ).toFixed(2)
            );
    }
}


// --------------------
// ANOMALY DETECTION
// --------------------

const anomalies = [];

const dailyValues =
    Object.values(dailyRevenue);

if (dailyValues.length >= 3) {

    const avgDailyRevenue =
        dailyValues.reduce((a, b) => a + b, 0)
        / dailyValues.length;

    for (const [date, revenue] of Object.entries(dailyRevenue)) {

        const differencePercent =
            ((revenue - avgDailyRevenue)
            / avgDailyRevenue) * 100;

        if (differencePercent >= 40) {

            anomalies.push(
                `${date}: Revenue spike of ${differencePercent.toFixed(1)}% above average`
            );
        }

        else if (differencePercent <= -40) {

            anomalies.push(
                `${date}: Revenue drop of ${Math.abs(differencePercent).toFixed(1)}% below average`
            );
        }
    }
}


// Store concentration warning
if (
    topStore[1] > 0 &&
    totalRevenue > 0
) {

    const storeShare =
        (topStore[1] / totalRevenue) * 100;

    if (storeShare >= 60) {

        anomalies.push(
            `${topStore[0]} contributes ${storeShare.toFixed(1)}% of total revenue, indicating high store concentration`
        );
    }
}


// Category concentration warning
if (
    topCategory[1] > 0 &&
    totalRevenue > 0
) {

    const categoryShare =
        (topCategory[1] / totalRevenue) * 100;

    if (categoryShare >= 60) {

        anomalies.push(
            `${topCategory[0]} contributes ${categoryShare.toFixed(1)}% of total revenue, indicating high category concentration`
        );
    }
}


// --------------------
// FINAL OUTPUT
// --------------------

return [
    {
        json: {

            // BASIC KPIs
            totalRevenue:
                Number(totalRevenue.toFixed(2)),

            totalTransactions,

            totalQuantitySold:
                totalQuantity,

            averageTransactionValue:
                Number(averageTransactionValue.toFixed(2)),


            // TOP PERFORMERS
            topStore: {
                name: topStore[0],
                revenue: Number(topStore[1].toFixed(2))
            },

            topCategory: {
                name: topCategory[0],
                revenue: Number(topCategory[1].toFixed(2))
            },

            topProduct: {
                name: topProduct[0],
                revenue: Number(topProduct[1].toFixed(2))
            },

            lowestProduct: {
                name: lowestProduct[0],
                revenue: Number(lowestProduct[1].toFixed(2))
            },


            // TIME INSIGHTS
            busiestHour: {
                hour: busiestHour[0],
                revenue: Number(busiestHour[1].toFixed(2))
            },

            slowestHour: {
                hour: slowestHour[0],
                revenue: Number(slowestHour[1].toFixed(2))
            },


            // DAY INSIGHTS
            bestDay: {
                date: bestDay[0],
                revenue: Number(bestDay[1].toFixed(2))
            },

            worstDay: {
                date: worstDay[0],
                revenue: Number(worstDay[1].toFixed(2))
            },

            dailyGrowthPercent,


            // ADVANCED ANALYTICS
            top5Products,
            bottom5Products,
            storeRanking,
            categoryContribution,


            // ANOMALIES
            anomalyCount:
                anomalies.length,

            anomalies,


            // DATA QUALITY
            dataQuality: {
                validRows,
                invalidRows,
                totalRows: items.length
            },


            // RAW AGGREGATIONS
            revenueByStore: storeRevenue,
            revenueByCategory: categoryRevenue,
            hourlyRevenue,
            dailyRevenue
        }
    }
];

