const items = $input.all();

const seenIds = new Set();

for (const item of items) {
    const d = item.json;

    const issues = [];

    // 1. Transaction ID
    if (
        d.transaction_id === undefined ||
        d.transaction_id === null ||
        String(d.transaction_id).trim() === ""
    ) {
        issues.push("Missing transaction_id");
    } 
    else {
        const id = String(d.transaction_id).trim();

        if (seenIds.has(id)) {
            issues.push("Duplicate transaction_id");
        } else {
            seenIds.add(id);
        }
    }

    // 2. Date
    if (
        d.transaction_date === undefined ||
        d.transaction_date === null ||
        String(d.transaction_date).trim() === ""
    ) {
        issues.push("Missing transaction_date");
    }

    // 3. Time
    if (
        d.transaction_time === undefined ||
        d.transaction_time === null ||
        String(d.transaction_time).trim() === ""
    ) {
        issues.push("Missing transaction_time");
    }

    // 4. Quantity
    const qty = Number(d.transaction_qty);

    if (d.transaction_qty === undefined || d.transaction_qty === null || isNaN(qty)) {
        issues.push("Invalid transaction_qty");
    } 
    else if (qty <= 0) {
        issues.push("Quantity must be greater than 0");
    }

    // 5. Unit Price
    const price = Number(d.unit_price);

    if (d.unit_price === undefined || d.unit_price === null || isNaN(price)) {
        issues.push("Invalid unit_price");
    } 
    else if (price <= 0) {
        issues.push("Unit price must be greater than 0");
    }

    // 6. Store
    if (!d.store_location || String(d.store_location).trim() === "") {
        issues.push("Missing store_location");
    }

    // 7. Product Category
    if (!d.product_category || String(d.product_category).trim() === "") {
        issues.push("Missing product_category");
    }

    // 8. Product Detail
    if (!d.product_detail || String(d.product_detail).trim() === "") {
        issues.push("Missing product_detail");
    }

    // Final quality status
    d.is_valid = issues.length === 0;

    d.data_quality_status =
        issues.length === 0 ? "Valid" : "Invalid";

    d.data_quality_issues =
        issues.length === 0 ? "None" : issues.join(", ");
}

return items;
